import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import {
	uv,
	color,
	mix,
	smoothstep,
	float,
	vec2,
	length,
	vec4,
	sub,
	greaterThan,
	lessThan,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
	const { Group, Mesh, PlaneGeometry, CylinderGeometry, CircleGeometry, DirectionalLight, Color } = ctx.THREE;

	// Root group (position/rotation/scale applied by adapter)
	const root = new Group();

	/* -------------------------------------------------------------------------
	 * Backdrop plane with vertical gradient (7 x 6 units at z = -2.5)
	 * ----------------------------------------------------------------------- */
	const backdropGeom = new PlaneGeometry(7, 6);
	const gradientStops = (config.visualSpec?.gradientStops ??
		[
			{ at: 0, hex: '#0b0b10' },
			{ at: 0.55, hex: '#101017' },
			{ at: 1, hex: '#16161d' },
		]);

	const backdropMat = new MeshStandardNodeMaterial();
	let gradNode = color(new Color(gradientStops[0].hex));
	for (let i = 1; i < gradientStops.length; i++) {
		const nextColor = color(new Color(gradientStops[i].hex));
		const t = smoothstep(float(gradientStops[i - 1].at), float(gradientStops[i].at), uv().y);
		gradNode = mix(gradNode, nextColor, t);
	}
	backdropMat.colorNode = gradNode;
	const backdrop = new Mesh(backdropGeom, backdropMat);
	backdrop.position.set(0, 0, -2.5);
	root.add(backdrop);

	/* -------------------------------------------------------------------------
	 * Plinth cylinder (radius 1.4, height 0.25, top at y = -1.1)
	 * ----------------------------------------------------------------------- */
	const plinthGeom = new CylinderGeometry(1.4, 1.4, 0.25, 32);
	const plinthMat = new MeshStandardNodeMaterial();
	plinthMat.colorNode = color(new Color('#14141a'));
	const plinth = new Mesh(plinthGeom, plinthMat);
	// center y = top - height/2
	plinth.position.set(0, -1.1 - 0.125, 0);
	root.add(plinth);

	/* -------------------------------------------------------------------------
	 * Contact shadow (radial gradient circle under plinth)
	 * ----------------------------------------------------------------------- */
	const shadowGeom = new CircleGeometry(1.6, 64);
	const shadowMat = new MeshStandardNodeMaterial();
	shadowMat.transparent = true;
	const uvNode = uv();
	const centered = sub(uvNode, vec2(0.5));
	const dist = length(centered);
	const alpha = smoothstep(float(0.0), float(0.5), float(1.0).sub(dist)).mul(float(0.55));
	shadowMat.colorNode = vec4(color(new Color('#0b0b10')), alpha);
	const shadow = new Mesh(shadowGeom, shadowMat);
	shadow.rotation.x = -Math.PI / 2;
	shadow.position.set(0, -1.125, 0); // just below plinth top
	root.add(shadow);

	/* -------------------------------------------------------------------------
	 * Load watch GLB (meshUrl)
	 * ----------------------------------------------------------------------- */
	const watchGroup = new Group();
	if (config.meshUrl) {
		ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
			if (gltf && gltf.scene) {
				watchGroup.add(gltf.scene);
			}
		});
	}
	root.add(watchGroup);

	/* -------------------------------------------------------------------------
	 * Lights
	 * ----------------------------------------------------------------------- */
	// Key light (warm white)
	const keyLight = new DirectionalLight(0xffffff, 1.2);
	keyLight.position.set(4, 5, 4);
	root.add(keyLight);

	// Rim / accent light (signal red)
	const rimLight = new DirectionalLight(0xff2a38, 0.8);
	rimLight.position.set(-4, 2, -2);
	root.add(rimLight);

	/* -------------------------------------------------------------------------
	 * Text content
	 * ----------------------------------------------------------------------- */
	const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
	const textGroup = new Group();
	const colorInk = (config.visualSpec?.colors?.ink) ?? '#16161d';
	const colorPaper = (config.visualSpec?.colors?.paper) ?? '#e8ecf2';

	for (const item of items) {
		if (!item.text) continue;
		const role = item.role ?? '';
		let fontSize = item.typography?.fontSize ?? 26;
		let color = colorPaper;
		if (role === 'headline') {
			fontSize = item.typography?.fontSize ?? 68;
			color = colorInk;
		} else if (role === 'caption') {
			fontSize = item.typography?.fontSize ?? 18;
			color = colorPaper;
		}
		const txt = ctx.fontAtlas.createText(item.text, {
			fontSize,
			color,
			align: 'center',
		});

		// Position according to role
		if (role === 'headline') {
			txt.position.set(0, -1.5, 0);
		} else if (role === 'body') {
			txt.position.set(0, -1.8, 0);
		} else if (role === 'caption') {
			txt.position.set(0, -2.0, 0);
		} else {
			txt.position.set(0, 0, 0);
		}
		textGroup.add(txt);
	}
	root.add(textGroup);

	/* -------------------------------------------------------------------------
	 * Apply cinematic primitives
	 * ----------------------------------------------------------------------- */
	const primitiveInstances = [];
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const prim of config.cinematicPrimitives) {
			if (prim && prim.name && typeof ctx.primitives[prim.name] === 'function') {
				const inst = ctx.primitives[prim.name](root, prim.params || {});
				if (inst) primitiveInstances.push(inst);
			}
		}
	}

	/* -------------------------------------------------------------------------
	 * Cleanup
	 * ----------------------------------------------------------------------- */
	root.userData.handlers = {};

	root.userData.cleanup = () => {
		// Dispose geometries and materials we created
		backdropGeom.dispose();
		backdropMat.dispose();

		plinthGeom.dispose();
		plinthMat.dispose();

		shadowGeom.dispose();
		shadowMat.dispose();

		// Dispose any GLB resources will be handled by three when scene is disposed
		// Clean up primitives
		for (const inst of primitiveInstances) {
			if (typeof inst.cleanup === 'function') inst.cleanup();
		}
	};

	return root;
}
